93	impl Debug for Matrix {
94	    fn fmt(&self, f: &mut fmt::Formatter) -> fmt::Result {
95	        writeln!(f)?;
96	        for i in 0..self.rows {
97	            for j in 0..self.cols {
98	                write!(f, "{:5}", self.get(i, j))?;
99	            }
100	            writeln!(f)?;
101	        }
102	        Ok(())
103	    }
104	}
